CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, notifications boolean NOT NULL DEFAULT false, private_account boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.salons (id text PRIMARY KEY, slug text NOT NULL UNIQUE, name text NOT NULL, city text NOT NULL, area text NOT NULL, published boolean NOT NULL DEFAULT false, archived boolean NOT NULL DEFAULT false, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.salons TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.salons TO authenticated; GRANT ALL ON public.salons TO service_role;
ALTER TABLE public.salons ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_salons ON public.salons FOR SELECT TO anon,authenticated USING(published AND NOT archived);
CREATE POLICY admin_salons ON public.salons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX salons_location_idx ON public.salons(city,area) WHERE published AND NOT archived;
CREATE INDEX salons_data_idx ON public.salons USING gin(data);
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id text NOT NULL REFERENCES public.salons(id), user_id uuid NOT NULL, author text NOT NULL, service text NOT NULL DEFAULT '', dims integer[] NOT NULL CHECK(array_length(dims,1)=6 AND dims <@ ARRAY[1,2,3,4,5]), text text NOT NULL CHECK(char_length(text) BETWEEN 30 AND 1500), title text NOT NULL DEFAULT '', visit_date date, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','hidden','reported')), kind text NOT NULL DEFAULT 'community' CHECK(kind IN ('community','verified-visit')), reply text, moderation_note text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reviews TO anon; GRANT SELECT,INSERT,UPDATE ON public.reviews TO authenticated; GRANT ALL ON public.reviews TO service_role;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_reviews ON public.reviews FOR SELECT TO anon,authenticated USING(status='approved' AND EXISTS(SELECT 1 FROM public.salons s WHERE s.id=salon_id AND s.published AND NOT s.archived));
CREATE POLICY own_reviews ON public.reviews FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY submit_review ON public.reviews FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND kind='community' AND reply IS NULL AND moderation_note IS NULL AND EXISTS(SELECT 1 FROM public.salons s WHERE s.id=salon_id AND s.published AND NOT s.archived));
CREATE POLICY admin_reviews ON public.reviews FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX one_active_review ON public.reviews(user_id,salon_id) WHERE status<>'rejected';
CREATE INDEX reviews_salon_status_idx ON public.reviews(salon_id,status,created_at DESC);
CREATE TABLE public.review_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES public.reviews(id) ON DELETE CASCADE, user_id uuid NOT NULL, storage_path text NOT NULL, accepted boolean NOT NULL DEFAULT false, checked_by uuid, checked_at timestamptz);
GRANT SELECT,INSERT,UPDATE ON public.review_evidence TO authenticated; GRANT ALL ON public.review_evidence TO service_role;
ALTER TABLE public.review_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY evidence_owner_read ON public.review_evidence FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY evidence_owner_insert ON public.review_evidence FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT accepted AND checked_by IS NULL AND checked_at IS NULL AND storage_path LIKE auth.uid()::text || '/%' AND EXISTS(SELECT 1 FROM public.reviews r WHERE r.id=review_id AND r.user_id=auth.uid()));
CREATE POLICY evidence_admin ON public.review_evidence FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_verified_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='verified-visit' AND NOT EXISTS(SELECT 1 FROM public.review_evidence WHERE review_id=NEW.id AND accepted AND checked_by IS NOT NULL AND checked_at IS NOT NULL) THEN RAISE EXCEPTION 'Accepted visit evidence is required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER verified_evidence_required BEFORE INSERT OR UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.validate_verified_review();
CREATE TABLE public.review_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES public.reviews(id), user_id uuid NOT NULL, reason text NOT NULL CHECK(char_length(reason) BETWEEN 3 AND 500), resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.review_reports TO authenticated; GRANT ALL ON public.review_reports TO service_role;
ALTER TABLE public.review_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_insert ON public.review_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT resolved);
CREATE POLICY reports_admin ON public.review_reports FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.favorites (user_id uuid NOT NULL, salon_id text NOT NULL REFERENCES public.salons(id) ON DELETE CASCADE, PRIMARY KEY(user_id,salon_id));
GRANT SELECT,INSERT,DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_favorites ON public.favorites FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.comparisons (user_id uuid PRIMARY KEY, salon_ids text[] NOT NULL DEFAULT '{}' CHECK(cardinality(salon_ids)<=3));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.comparisons TO authenticated; GRANT ALL ON public.comparisons TO service_role;
ALTER TABLE public.comparisons ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_comparison ON public.comparisons FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.partnership_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business text NOT NULL CHECK(char_length(business) BETWEEN 2 AND 150), name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 150), phone text NOT NULL CHECK(phone ~ '^09[0-9]{9}$'), city text NOT NULL, area text NOT NULL DEFAULT '', categories text[] NOT NULL DEFAULT '{}', instagram text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', message text NOT NULL DEFAULT '' CHECK(char_length(message)<=1000), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','accepted','closed')), internal_note text NOT NULL DEFAULT '', salon_id text REFERENCES public.salons(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.partnership_requests TO anon; GRANT SELECT,INSERT,UPDATE ON public.partnership_requests TO authenticated; GRANT ALL ON public.partnership_requests TO service_role;
ALTER TABLE public.partnership_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_insert ON public.partnership_requests FOR INSERT TO anon,authenticated WITH CHECK(status='new' AND internal_note='' AND salon_id IS NULL);
CREATE POLICY request_admin ON public.partnership_requests FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.partnership_requests(id), read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.admin_notifications TO authenticated; GRANT ALL ON public.admin_notifications TO service_role;
ALTER TABLE public.admin_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_notifications ON public.admin_notifications FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.notify_partnership() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.admin_notifications(request_id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER notify_new_request AFTER INSERT ON public.partnership_requests FOR EACH ROW EXECUTE FUNCTION public.notify_partnership();
CREATE TABLE public.admin_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, entity text NOT NULL, record_id text NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit_logs TO authenticated; GRANT ALL ON public.admin_audit_logs TO service_role;
ALTER TABLE public.admin_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit ON public.admin_audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_admin_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.has_role(auth.uid(),'admin') THEN INSERT INTO public.admin_audit_logs(actor_id,entity,record_id,action) VALUES(auth.uid(),TG_TABLE_NAME,COALESCE(NEW.id::text,OLD.id::text),TG_OP); END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER audit_salons AFTER INSERT OR UPDATE OR DELETE ON public.salons FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER audit_reviews AFTER UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER audit_requests AFTER UPDATE ON public.partnership_requests FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TABLE public.discovery_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(char_length(name)<80), props jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.discovery_events TO anon; GRANT SELECT,INSERT ON public.discovery_events TO authenticated; GRANT ALL ON public.discovery_events TO service_role;
ALTER TABLE public.discovery_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_insert ON public.discovery_events FOR INSERT TO anon,authenticated WITH CHECK(octet_length(props::text)<1024 AND NOT props ?| ARRAY['phone','email','text','name','password','token']);
CREATE POLICY event_admin_read ON public.discovery_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
